  r'test',
  """test
    test""",
  \'\'\'test
    test\'\'\',
  r"""test
    test""",
  r\'\'\'test
    test\'\'\'
];

final constListInterpolation = const [
  '\${'test'}'
  '\${'\${'test'}'}',
  '\${'test'} \${10500 - 500}  \${((1 == 2) != ("" == "b")) == (!identical(false, true))}',
  '\${'\${'test'} \${10500 - 500}  \${((1 == 2) != ("" == "b")) == (!identical(false, true))}'}',
  '\${1.0/0.0}',
  '\${0.0/0.0}',
  '\${(3.14 * 15926) + (1 ~/ 100)}',
  '\${~(((1 + 2) ~/ 2) & (100500 >> 2))  | (~1 ^ (1<<2))}'
  "\${'a''b'}",
  '\${1}',
  "{1 + 1}",
  '\${true}',
  '\${2 > 1}',
  '\${null}'
];

final constListConcatenation = const [
  '' '',
  "a""b",
  r"1" r'2',
  \'\'\'a
  a\'\'\' """bb"""
];

main() {
  Expect.isTrue(constList is List);
  Expect.isTrue(constListInterpolation is List);
  Expect.isTrue(constListConcatenation is List);
  Expect.runtimeIsType<List>(constList);
  Expect.runtimeIsType<List>(constListInterpolation);
  Expect.runtimeIsType<List>(constListConcatenation);
}

