    Expect.fail("NoSuchMethodError expected.");
  } on NoSuchMethodError catch (ok) {}

  try {
    c..m1()..sm()..m2();
    Expect.fail("NoSuchMethodError expected.");
  } on NoSuchMethodError catch (ok) {}
  Expect.equals(1, c.i1, "m1 was not executed");
  Expect.equals(0, c.i2, "m2 was executed");
}

