int    f3(int x, int y)    => x % y;
double f4(int x, double y) => x % y;
int    f5(int x, int y)    => x ~/ y;

main () {
  f1(4, 3);
  f2(4, 3.0);
  f3(4, 3);
  f4(4, 3.0);
  f5(4, 3);
}

