  Expect.equals(true, classWithGetter2.v);

  dynamic classWithGetter3 = new C();
  Expect.equals(1, classWithGetter3.v);

  dynamic classWithGetter4 = new D();
  Expect.equals(null, classWithGetter4.v);
}

