    test('Strings > ignore_whitespaces_t01', () {
      final plugin = Co19ExpectPlugin();
      final compiler = Compiler();
      compiler.addPlugin(plugin);
      final runtime = compiler.compileWriteAndLoad({
        'co19_test': {
          'main.dart': '''
// Copyright (c) 2011, the Dart project authors.  Please see the AUTHORS file
// for details. All rights reserved. Use of this source code is governed by a
// BSD-style license that can be found in the LICENSE file.

/// @assertion If the first line of a multiline string consists solely of the
/// whitespace characters defined by the production WHITESPACE, possibly
/// prefixed by \\, then that line is ignored, including the new line at its end.
/// @description Checks that the first new-line in a multi-line string is
/// ignored.
/// @author iefremov

import 'package:co19_expect/expect.dart';


main() {
  var s1 = """
""";
  Expect.stringEquals("""""", s1,
      "The first new-line character in a multi-line string should be ignored!");

  s1 = \'\'\'
\'\'\';
  Expect.stringEquals(\'\'\'\'\'\', s1,
      "The first new-line character in a multi-line string should be ignored!");

  // newline prefixed by \\
  s1 = """\\
""";
  Expect.stringEquals("""""", s1,
      "The first new-line character in a multi-line string should be ignored!");

  s1 = \'\'\'\\
\'\'\';
  Expect.stringEquals(\'\'\'\'\'\', s1,
      "The first new-line character in a multi-line string should be ignored!");

  // space and newline prefixed by \\
  s1 = """\\ \\
""";
  Expect.stringEquals("""""", s1,
      "The first new-line character in a multi-line string should be ignored!");

  s1 = \'\'\'\\ \\
\'\'\';
  Expect.stringEquals(\'\'\'\'\'\', s1,
      "The first new-line character in a multi-line string should be ignored!");

  // tabs and spaces at the beginning of a multiline string
  s1 = """  	  
abyr, abyr
abyrvalg
""";
  Expect.stringEquals("""abyr, abyr
abyrvalg
""", s1);
}

'''
        }
      });
      plugin.configureForRuntime(runtime);
      runtime.executeLib('package:co19_test/main.dart', 'main');
    });
    test('Strings > implement_class_string_t01', () {
      final plugin = Co19ExpectPlugin();
      final compiler = Compiler();
      compiler.addPlugin(plugin);
      final runtime = compiler.compileWriteAndLoad({
        'co19_test': {
          'main.dart': '''
// Copyright (c) 2011, the Dart project authors.  Please see the AUTHORS file
// for details. All rights reserved. Use of this source code is governed by a
// BSD-style license that can be found in the LICENSE file.

/// @assertion All string literals implement the built-in class String.
/// @description Checks that string literals implement class String.
/// @author msyabro

import 'package:co19_expect/expect.dart';

main() {
  Expect.isTrue("" is String);
  Expect.isTrue('' is String);
  Expect.isTrue(r"" is String);
  Expect.isTrue(r'' is String);
  Expect.isTrue("""""" is String);
  Expect.isTrue(\'\'\'\'\'\' is String);
  Expect.isTrue(r"""""" is String);
  Expect.isTrue(r\'\'\'\'\'\' is String);
  Expect.runtimeIsType<String>("");
