  Expect.equals(0, 0 as num);
  Expect.equals("foo", "foo" as String);
  Expect.equals("bar", "bar" as Pattern);

  var c = null;
  Expect.equals(null, c as num?);

  c = C(1);
  Expect.identical(c, c as I);

  Expect.throws(() { c = 1 as I; }, (e) => e is TypeError);
}

